using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;
public static class InspectCathedralProps{
public static string Run(){var files=Directory.GetFiles("Assets/3DBattle/Boss2/Cathedral","*.fbx",SearchOption.AllDirectories).OrderBy(x=>x).ToArray();var go=new GameObject("Temporary prop camera");go.hideFlags=HideFlags.HideAndDontSave;var cam=go.AddComponent<Camera>();cam.enabled=false;cam.orthographic=true;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.22f,.24f,.28f);var rt=new RenderTexture(400,360,24);var tex=new Texture2D(1600,720,TextureFormat.RGB24,false);var old=RenderTexture.active;string log="";GameObject obj=null;Material mat=null;
try{cam.targetTexture=rt;for(int row=0;row<files.Length;row++){string path=files[row].Replace('\\','/');obj=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(path));obj.hideFlags=HideFlags.HideAndDontSave;obj.transform.position=new Vector3(1000,0,1000);mat=new Material(Shader.Find("Universal Render Pipeline/Unlit"));mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Path.ChangeExtension(path,".png")));mat.SetFloat("_Cull",0);var rs=obj.GetComponentsInChildren<Renderer>();foreach(var r in rs)r.sharedMaterial=mat;var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);log+=Path.GetFileName(path)+" size="+b.size+"\n";cam.orthographicSize=b.size.magnitude*.58f;for(int i=0;i<4;i++){var dir=Quaternion.Euler(0,i*90,0)*new Vector3(0,.4f,1);cam.transform.position=b.center+dir*b.size.magnitude*3;cam.transform.LookAt(b.center);cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,400,360),i*400,(1-row)*360);}UnityEngine.Object.DestroyImmediate(obj);obj=null;UnityEngine.Object.DestroyImmediate(mat);mat=null;}tex.Apply();File.WriteAllBytes("Assets/3DBattle/Authoring~/CathedralPropsSource.png",tex.EncodeToPNG());return log;}
finally{RenderTexture.active=old;cam.targetTexture=null;if(obj!=null)UnityEngine.Object.DestroyImmediate(obj);if(mat!=null)UnityEngine.Object.DestroyImmediate(mat);UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}}
